// qx for omp: runs omp's own `bash` commands through qx, which captures and compacts their output.
//
// omp mounts MCP tools under `xd://`, so the model rarely calls qx there; this hook reaches the
// shell it already uses, at no prompt cost. `qx hook omp` gets the bash input and prints the input
// to run instead, or nothing to leave it alone. omp checks its approval rules on the new line.
// Generated by `qx setup omp`; `__QX_EXE__` is replaced with the installed qx path.
import { spawnSync } from "node:child_process";

const EXE = "__QX_EXE__";

export default function (pi) {
  pi.on("tool_call", (event) => {
    if (event.toolName !== "bash") return;
    const r = spawnSync(EXE, ["hook", "omp"], {
      input: JSON.stringify(event.input),
      encoding: "utf8",
      timeout: 5000,
      windowsHide: true,
    });
    // Any doubt (qx missing, slow, or silent): omp runs the command as it was.
    if (r.status !== 0 || !r.stdout || !r.stdout.trim()) return;
    try {
      return { input: JSON.parse(r.stdout) };
    } catch {
      return;
    }
  });
}
